// n8n Ops Pack v1 — Stripe signature verify + typed parse
// Requires n8n 1.40+ Code node. crypto is allowed in standard n8n.
const crypto = require('crypto');

const item = $input.first();
const headers = item.json.headers || {};
const headerLower = {};
for (const [k, v] of Object.entries(headers)) {
  headerLower[String(k).toLowerCase()] = v;
}

const skipVerify = String($env.STRIPE_SKIP_VERIFY || '').toLowerCase() === 'true';
const secret = $env.STRIPE_WEBHOOK_SECRET || '';
const toleranceSec = Number($env.STRIPE_TOLERANCE_SEC || 300);

function looksBase64(s) {
  if (typeof s !== 'string' || s.length < 8) return false;
  return /^[A-Za-z0-9+/]+=*$/.test(s.replace(/\s/g, ''));
}

function getRawBody() {
  if (item.binary && item.binary.data) {
    const bin = item.binary.data;
    if (typeof bin.data === 'string') {
      const encoding = looksBase64(bin.data) ? 'base64' : 'utf8';
      return Buffer.from(bin.data, encoding).toString('utf8');
    }
  }
  if (typeof item.json.rawBody === 'string') return item.json.rawBody;
  if (typeof item.json.body === 'string') return item.json.body;
  if (item.json.body && typeof item.json.body === 'object') {
    return JSON.stringify(item.json.body);
  }
  // Last resort: whole json minus headers/query/params
  const clone = { ...item.json };
  delete clone.headers;
  delete clone.query;
  delete clone.params;
  delete clone.webhookUrl;
  delete clone.executionMode;
  return JSON.stringify(clone.body || clone);
}

function unwrapEvent(parsed) {
  if (parsed && parsed.type && parsed.id && parsed.data) return parsed;
  if (parsed && parsed.body && parsed.body.type && parsed.body.id) return parsed.body;
  throw new Error('Body is JSON but not a Stripe Event (missing id/type/data).');
}

const rawBody = getRawBody();
let event;
try {
  event = unwrapEvent(JSON.parse(rawBody));
} catch (err) {
  throw new Error('Invalid Stripe event JSON: ' + err.message);
}

if (!skipVerify) {
  if (!secret) {
    throw new Error(
      'STRIPE_WEBHOOK_SECRET is empty. Set it on the n8n instance, or set STRIPE_SKIP_VERIFY=true for local tests ONLY.'
    );
  }
  const sigHeader = headerLower['stripe-signature'];
  if (!sigHeader) {
    throw new Error('Missing Stripe-Signature header. Stripe always sends this.');
  }
  const parts = {};
  for (const piece of String(sigHeader).split(',')) {
    const eq = piece.indexOf('=');
    if (eq === -1) continue;
    const k = piece.slice(0, eq).trim();
    const v = piece.slice(eq + 1).trim();
    if (!parts[k]) parts[k] = [];
    parts[k].push(v);
  }
  const timestamp = parts.t && parts.t[0];
  const v1s = parts.v1 || [];
  if (!timestamp || v1s.length === 0) {
    throw new Error('Malformed Stripe-Signature header (need t= and v1=).');
  }
  const tsNum = Number(timestamp);
  const now = Math.floor(Date.now() / 1000);
  if (!Number.isFinite(tsNum) || Math.abs(now - tsNum) > toleranceSec) {
    throw new Error(
      'Stripe timestamp outside tolerance (' +
        toleranceSec +
        's). Possible replay, or n8n clock skew.'
    );
  }
  const signedPayload = timestamp + '.' + rawBody;
  const expectedHex = crypto.createHmac('sha256', secret).update(signedPayload, 'utf8').digest('hex');
  const expectedBuf = Buffer.from(expectedHex, 'utf8');
  let ok = false;
  for (const v1 of v1s) {
    const got = Buffer.from(v1, 'utf8');
    if (got.length === expectedBuf.length && crypto.timingSafeEqual(got, expectedBuf)) {
      ok = true;
      break;
    }
  }
  if (!ok) {
    throw new Error(
      'Stripe signature mismatch. Usual causes: wrong STRIPE_WEBHOOK_SECRET (test vs live), or the webhook node re-serialized JSON so the raw body no longer matches. Enable "Raw Body" on the Webhook node (already on in this pack) and do not put a reverse proxy that rewrites the body.'
    );
  }
}

const obj = (event.data && event.data.object) || {};
const amount =
  obj.amount_received ??
  obj.amount_paid ??
  obj.amount_captured ??
  obj.amount ??
  obj.amount_due ??
  null;
const currency = (obj.currency || '').toLowerCase();
const customer = obj.customer || obj.customer_email || null;

return [
  {
    json: {
      eventId: event.id,
      type: event.type,
      created: event.created || null,
      createdIso: event.created ? new Date(event.created * 1000).toISOString() : null,
      livemode: Boolean(event.livemode),
      apiVersion: event.api_version || null,
      requestId: event.request && event.request.id ? event.request.id : null,
      account: event.account || null,
      objectId: obj.id || null,
      objectType: obj.object || null,
      amount: amount,
      amountFormatted:
        amount != null && currency
          ? (Number(amount) / 100).toFixed(2) + ' ' + currency.toUpperCase()
          : amount != null
            ? String(amount)
            : null,
      currency: currency || null,
      customer: customer,
      status: obj.status || null,
      paymentIntent: obj.payment_intent || (obj.object === 'payment_intent' ? obj.id : null),
      invoice: obj.invoice || (obj.object === 'invoice' ? obj.id : null),
      subscription: obj.subscription || (obj.object === 'subscription' ? obj.id : null),
      description: obj.description || obj.billing_reason || obj.reason || null,
      objectSummary: {
        id: obj.id || null,
        object: obj.object || null,
        status: obj.status || null,
      },
      signatureVerified: !skipVerify,
    },
  },
];

// Idempotent log: remember Stripe event.id on this n8n instance.
// HONEST LIMIT: getWorkflowStaticData is per-instance (not shared across
// queue workers / multiple mains). Last N ids only. Not a ledger.
const MAX_IDS = Number($env.IDEMPOTENCY_MAX_IDS || 2000);
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.processedEventIds)) staticData.processedEventIds = [];
if (!staticData.processedAt || typeof staticData.processedAt !== 'object') staticData.processedAt = {};
if (!Array.isArray(staticData.log)) staticData.log = [];

const incoming = $input.first().json;
const eventId = incoming.eventId;
if (!eventId) {
  throw new Error('Missing eventId after parse — refusing to process.');
}

const duplicate = staticData.processedEventIds.includes(eventId);
const nowIso = new Date().toISOString();
if (!duplicate) {
  staticData.processedEventIds.push(eventId);
  staticData.processedAt[eventId] = nowIso;
  if (staticData.processedEventIds.length > MAX_IDS) {
    const overflow = staticData.processedEventIds.length - MAX_IDS;
    const dropped = staticData.processedEventIds.splice(0, overflow);
    for (const id of dropped) delete staticData.processedAt[id];
  }
}

return [
  {
    json: {
      ...incoming,
      duplicate,
      firstSeenAt: staticData.processedAt[eventId] || nowIso,
      processedCount: staticData.processedEventIds.length,
      idempotencyStore: 'workflow-static-data',
    },
  },
];

// Map Stripe event.type → severity, title, Slack/Discord/email payloads.
const e = $input.first().json;

const CATALOG = {
  'payment_intent.succeeded': { severity: 'info', title: 'Payment succeeded' },
  'payment_intent.payment_failed': { severity: 'error', title: 'Payment failed' },
  'payment_intent.canceled': { severity: 'warn', title: 'Payment canceled' },
  'charge.succeeded': { severity: 'info', title: 'Charge succeeded' },
  'charge.failed': { severity: 'error', title: 'Charge failed' },
  'charge.refunded': { severity: 'warn', title: 'Charge refunded' },
  'charge.dispute.created': { severity: 'critical', title: 'Dispute opened' },
  'charge.dispute.closed': { severity: 'info', title: 'Dispute closed' },
  'invoice.paid': { severity: 'info', title: 'Invoice paid' },
  'invoice.payment_failed': { severity: 'error', title: 'Invoice payment failed' },
  'invoice.finalized': { severity: 'low', title: 'Invoice finalized' },
  'customer.subscription.created': { severity: 'info', title: 'Subscription created' },
  'customer.subscription.updated': { severity: 'info', title: 'Subscription updated' },
  'customer.subscription.deleted': { severity: 'warn', title: 'Subscription canceled' },
  'customer.subscription.paused': { severity: 'warn', title: 'Subscription paused' },
  'checkout.session.completed': { severity: 'info', title: 'Checkout completed' },
  'checkout.session.expired': { severity: 'warn', title: 'Checkout expired' },
  'radar.early_fraud_warning.created': { severity: 'critical', title: 'Early fraud warning' },
  'payout.paid': { severity: 'info', title: 'Payout paid' },
  'payout.failed': { severity: 'error', title: 'Payout failed' },
};

const meta = CATALOG[e.type] || { severity: 'low', title: e.type };
const mode = e.livemode ? 'LIVE' : 'TEST';

const lines = [
  '*' + meta.title + '* (' + mode + ')',
  'Type: `' + e.type + '`',
  'Event: `' + e.eventId + '`',
];
if (e.amountFormatted) lines.push('Amount: *' + e.amountFormatted + '*');
if (e.objectId) lines.push('Object: `' + (e.objectType || 'object') + '` `' + e.objectId + '`');
if (e.status) lines.push('Status: ' + e.status);
if (e.customer) lines.push('Customer: `' + e.customer + '`');
if (e.subscription) lines.push('Subscription: `' + e.subscription + '`');
if (e.invoice) lines.push('Invoice: `' + e.invoice + '`');
if (e.account) lines.push('Connect account: `' + e.account + '`');
if (e.description) lines.push('Note: ' + e.description);
lines.push('When: ' + (e.createdIso || 'unknown'));
const text = lines.join('\n');

const color =
  meta.severity === 'critical' || meta.severity === 'error'
    ? 0xe01e5a
    : meta.severity === 'warn'
      ? 0xecb22e
      : 0x2eb67d;

const slackUrl = $env.SLACK_WEBHOOK_URL || '';
const discordUrl = $env.DISCORD_WEBHOOK_URL || '';
const resendKey = $env.RESEND_API_KEY || '';
const alertTo = $env.ALERT_TO_EMAIL || '';
const alertFrom = $env.ALERT_FROM_EMAIL || '';

return [
  {
    json: {
      eventId: e.eventId,
      type: e.type,
      livemode: e.livemode,
      amountFormatted: e.amountFormatted,
      objectId: e.objectId,
      duplicate: e.duplicate,
      processedCount: e.processedCount,
      firstSeenAt: e.firstSeenAt,
      signatureVerified: e.signatureVerified,
      severity: meta.severity,
      title: meta.title,
      knownType: Object.prototype.hasOwnProperty.call(CATALOG, e.type),
      alertText: text,
      emailSubject: '[Stripe ' + mode + '] ' + meta.title + (e.amountFormatted ? ' · ' + e.amountFormatted : ''),
      emailHtml:
        '<p><strong>' +
        meta.title +
        '</strong> <code>' +
        mode +
        '</code></p><pre style="font-family:ui-monospace,monospace;white-space:pre-wrap">' +
        text.replace(/[*`]/g, '') +
        '</pre><p style="color:#666;font-size:12px">n8n Ops Pack v1 — Stripe typed event router. This is an operational alert, not a receipt.</p>',
      slackBody: {
        text: '[Stripe ' + mode + '] ' + meta.title,
        blocks: [
          {
            type: 'header',
            text: { type: 'plain_text', text: (meta.title + ' (' + mode + ')').slice(0, 150), emoji: true },
          },
          { type: 'section', text: { type: 'mrkdwn', text: text.slice(0, 2900) } },
        ],
      },
      discordBody: {
        content: '[Stripe ' + mode + '] **' + meta.title + '**',
        embeds: [
          {
            title: meta.title,
            description: text.replace(/\*/g, '').replace(/`/g, '').slice(0, 4000),
            color: color,
          },
        ],
      },
      channels: {
        slack: slackUrl.length > 8,
        discord: discordUrl.length > 8,
        email: resendKey.length > 8 && alertTo.indexOf('@') !== -1 && alertFrom.indexOf('@') !== -1,
      },
    },
  },
];

// Fire Slack / Discord / Resend. Optional channels are skipped, not failed.
// Uses this.helpers.httpRequest (n8n 1.40+). Failures are recorded, not thrown,
// so Stripe still gets 200 and does not retry forever on a bad Slack URL.
const helpers = this.helpers;
const e = $input.first().json;
const notify = { slack: 'skipped', discord: 'skipped', email: 'skipped', errors: [] };

if (e.channels && e.channels.slack && $env.SLACK_WEBHOOK_URL) {
  try {
    await helpers.httpRequest({
      method: 'POST',
      url: $env.SLACK_WEBHOOK_URL,
      headers: { 'content-type': 'application/json' },
      body: e.slackBody,
      json: true,
    });
    notify.slack = 'ok';
  } catch (err) {
    notify.slack = 'error';
    notify.errors.push('slack: ' + err.message);
  }
}

if (e.channels && e.channels.discord && $env.DISCORD_WEBHOOK_URL) {
  try {
    await helpers.httpRequest({
      method: 'POST',
      url: $env.DISCORD_WEBHOOK_URL,
      headers: { 'content-type': 'application/json' },
      body: e.discordBody,
      json: true,
    });
    notify.discord = 'ok';
  } catch (err) {
    notify.discord = 'error';
    notify.errors.push('discord: ' + err.message);
  }
}

if (e.channels && e.channels.email && $env.RESEND_API_KEY) {
  try {
    await helpers.httpRequest({
      method: 'POST',
      url: 'https://api.resend.com/emails',
      headers: {
        'content-type': 'application/json',
        authorization: 'Bearer ' + $env.RESEND_API_KEY,
      },
      body: {
        from: $env.ALERT_FROM_EMAIL,
        to: [$env.ALERT_TO_EMAIL],
        subject: e.emailSubject,
        html: e.emailHtml,
      },
      json: true,
    });
    notify.email = 'ok';
  } catch (err) {
    notify.email = 'error';
    notify.errors.push('email: ' + err.message);
  }
}

return [{ json: { ...e, notify } }];

// Append a compact ops log row into workflow static data (last 200 rows).
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.log)) staticData.log = [];
const e = $input.first().json;
const row = {
  at: new Date().toISOString(),
  eventId: e.eventId,
  type: e.type,
  severity: e.severity,
  livemode: e.livemode,
  amountFormatted: e.amountFormatted || null,
  objectId: e.objectId || null,
  notify: e.notify || null,
};
staticData.log.push(row);
if (staticData.log.length > 200) {
  staticData.log.splice(0, staticData.log.length - 200);
}
return [{ json: { ...e, logRow: row, logLength: staticData.log.length } }];
